import fs from 'node:fs';
import path from 'node:path';
import { targetManifest } from './php-target.mjs';
import { compileTypePhp } from './typephp-compiler.mjs';
import { typePhpSources } from './typephp-sources.mjs';
import { writeBundleModule } from './bundle-module.mjs';

/** Compile before publishing either of the Worker entry modules. */
export function writeTypePhpBundle(generator, manifest, files, outputFile) {
	manifest = targetManifest(manifest, 'typephp');
	const { sources, compiledFiles } = typePhpSources({ manifest, files });
	const parent = path.dirname(outputFile);
	fs.mkdirSync(parent, { recursive: true });
	const temporary = fs.mkdtempSync(path.join(parent, '.typephp-stage-'));
	try {
		const result = compileTypePhp({ sources, outputDir: path.join(temporary, 'compiled') });
		const artifacts = path.join(parent, '.typephp', result.sourceHash);
		fs.mkdirSync(path.dirname(artifacts), { recursive: true });
		if (fs.existsSync(artifacts)) {
			if (!fs.lstatSync(artifacts).isDirectory()) throw new Error('TypePHP artifact path is not a plain directory');
			const previous = JSON.parse(fs.readFileSync(path.join(artifacts, 'typephp-build.json'), 'utf8'));
			if (previous.componentHash !== result.componentHash) {
				throw new Error('The same TypePHP inputs produced different WebAssembly bytes; the previous bundle was retained');
			}
		} else {
			fs.renameSync(path.join(temporary, 'compiled'), artifacts);
		}
		const relativeImport = (file) => './' + path.relative(parent, file).split(path.sep).join('/');
		const imports = [
			`import { instantiate } from ${JSON.stringify(relativeImport(path.join(artifacts, result.entry)))};`,
			`import { bootTypePhp, guestMemoryBytes } from ${JSON.stringify('./typephp-host.js')};`,
		];
		const modules = [];
		for (const [index, file] of result.modules.entries()) {
			imports.push(`import core${index} from ${JSON.stringify(relativeImport(path.join(artifacts, file)))};`);
			modules.push(`${JSON.stringify(path.basename(file))}: core${index}`);
		}
		const runtime = '// Generated by TypePHP bundle staging.\n' + imports.join('\n') + '\n'
			+ `const coreModules = { ${modules.join(', ')} };\n`
			+ 'export function bootPHP(doors) { return bootTypePhp({ instantiate, coreModules, ...doors }); }\n'
			+ 'export { guestMemoryBytes };\n';
		writeBundleModule(generator, {
			...manifest,
			compiler: {
				name: 'typephp', version: result.compilerVersion,
				source_hash: result.sourceHash, wasm_hash: result.componentHash,
				compiled_files: compiledFiles,
			},
		}, files, outputFile, runtime);
	} finally {
		fs.rmSync(temporary, { recursive: true, force: true });
	}
}
